(function(){window.PhysicaRankPyqNeet_physics_rayopticsandopticalinstruments=[{id:"neet-2026r-q008",pn:8,y:"Re-NEET 2026 \xB7 21 Jun",tp:"Ray Optics and Optical Instruments",st:"Apparent depth, refraction at a plane",q:"Consider three media P, Q and R with refractive indices 1, 1.25, and 1.5 respectively. The medium Q having a thickness of 5 cm is placed between extended media P and R as shown in the figure. An object O is placed at the centre of medium Q. If viewed from medium P near the normal direction, the apparent depth of O is h\u2081. For similar observation from medium R, the apparent depth is h\u2082. The value of |h\u2081 \u2013 h\u2082|, in cm, is:",o:["1","2","3","0"],c:0,s:`(i) Object viewed from medium P (real depth = 2.5 cm in Q).
Apparent depth h\u2081 = h_real/\u03BC = 2.5/1.25 = 2 cm.
(ii) Object viewed from medium R.
Apparent depth h\u2082 = (Q\u03BC_R) \xD7 2.5, taking the refractive index of R relative to Q.
h\u2082 = 2.5 \xD7 (1.5/1.25) = 3 cm.
So |h\u2081 \u2013 h\u2082| = 1 cm.`,fig:{w:195,h:200,alt:"Medium Q (n = 1.25, 5 cm thick) between P (n = 1) above and R (n = 1.5) below, with object O in the middle of Q.",d:[["l",10,5,10,60,"d"],["l",185,5,185,60,"d"],["r",10,60,175,70],["r",10,130,175,65,"f"],["t",180,45,"nP = 1","es"],["t",180,122,"nQ = 1.25","es"],["t",180,190,"nR = 1.5","es"],["l",36,80,36,68,"a"],["l",36,110,36,122,"a"],["t",36,100,"5 cm","ms"],["c",96,87,1.5,"F"],["t",86,85,"O","e"]]},sfig:{w:195,h:200,alt:"Medium Q (n = 1.25, 5 cm thick) between P (n = 1) above and R (n = 1.5) below, with object O in the middle of Q.",d:[["l",10,5,10,60,"d"],["l",185,5,185,60,"d"],["r",10,60,175,70],["r",10,130,175,65,"f"],["t",180,45,"nP = 1","es"],["t",180,122,"nQ = 1.25","es"],["t",180,190,"nR = 1.5","es"],["l",36,80,36,68,"a"],["l",36,110,36,122,"a"],["t",36,100,"5 cm","ms"],["c",96,87,1.5,"F"],["t",86,85,"O","e"]]}},{id:"neet-2026-q019",pn:19,y:"NEET 2026 \xB7 3 May",tp:"Ray Optics and Optical Instruments",st:"Concave lens refraction",q:"In a concave lens, a ray of light emanating from the object parallel to the principal axis of the lens after refraction:",o:["emerges parallel to the principal axis.","appears to diverge from the first principal focus.","passes through 2F, which is the radius of curvature of the lens.","passes through the second principal focus."],c:1,s:`For a concave lens, F\u2082 (second principal focus) is the virtual image position for an object at infinity.
F\u2081 (first principal focus) is the virtual object position for which the image is formed at infinity.
The publisher says the best answer is option (2), although it should strictly be the second principal focus.
Note: printed answer [2*]; the asterisk marks the answer as doubtful: the publisher notes the ray appears to diverge from the second principal focus (F\u2082), and calls option (2) the best available`,sfig:{w:300,h:280,alt:"Two ray diagrams of a concave lens: parallel rays diverge as if from the second focus F2; rays directed towards the first focus F1 emerge parallel",d:[["l",0,62,297,62],["p","M149 30 Q161 66 149 102"],["p","M171 30 Q159 66 171 102"],["l",149,30,171,30],["l",149,102,171,102],["l",85,30,148,30,"a"],["l",152,30,215,0,"a"],["l",85,90,152,90,"a"],["l",152,90,215,128,"a"],["l",108,62,152,30,"d"],["l",108,62,152,90,"d"],["t",100,80,"F\u2082"],["l",0,205,297,205],["p","M139 172 Q151 208 139 244"],["p","M161 172 Q149 208 161 244"],["l",139,172,161,172],["l",139,244,161,244],["l",50,168,143,195,"a"],["l",143,195,215,195,"a"],["l",143,195,185,205,"d"],["l",60,252,143,222,"a"],["l",143,222,215,222,"a"],["l",143,222,185,205,"d"],["t",188,238,"F\u2081"]]}},{id:"neet-2026-q023",pn:23,y:"NEET 2026 \xB7 3 May",tp:"Ray Optics and Optical Instruments",st:"Prism deviation",q:"A ray of monochromatic light is passing through an equilateral prism (ABC) as shown in the figure. The refracted ray (QR) is parallel to its base (BC) and the angle of incidence (i) is 50\xB0. Then the angle of deviation (\u03B4) is:",o:["40\xB0","45\xB0","55\xB0","35\xB0"],c:0,s:`QR is parallel to the base, so the ray passes symmetrically and i = e.
Prism equation: i + e = A + \u03B4.
2i \u2212 A = \u03B4.
2(50) \u2212 60 = \u03B4.
\u03B4 = 40\xB0.`,fig:{w:300,h:180,alt:"Equilateral prism ABC, 60\xB0 at A, incident ray PQ, refracted ray QR parallel to base BC, emergent ray RS and deviation \u03B4",d:[["p","M130 18 L40 155 L222 155 Z"],["l",45,155,37,163],["l",56,155,48,163],["l",67,155,59,163],["l",78,155,70,163],["l",89,155,81,163],["l",100,155,92,163],["l",111,155,103,163],["l",122,155,114,163],["l",133,155,125,163],["l",144,155,136,163],["l",155,155,147,163],["l",166,155,158,163],["l",177,155,169,163],["l",188,155,180,163],["l",199,155,191,163],["l",210,155,202,163],["l",221,155,213,163],["l",40,155,222,155],["t",126,10,"A"],["t",28,172,"B"],["t",224,172,"C"],["t",14,124,"P"],["t",89,98,"Q"],["t",164,98,"R"],["t",282,134,"S"],["p","M117 41 Q130 52 143 41","s"],["t",130,64,"60\xB0","ms"],["l",32,114,87,83,"a"],["l",87,83,172,83,"a"],["l",172,83,278,120,"a"],["l",87,83,200,64,"d"],["l",87,83,172,83,"d"],["t",46,92,"i","s"],["t",203,80,"\u03B4","s"]]},sfig:{w:300,h:180,alt:"Equilateral prism ABC with incidence angle i at Q and emergence angle e at R, ray QR parallel to the base",d:[["p","M130 18 L40 155 L222 155 Z"],["l",45,155,37,163],["l",56,155,48,163],["l",67,155,59,163],["l",78,155,70,163],["l",89,155,81,163],["l",100,155,92,163],["l",111,155,103,163],["l",122,155,114,163],["l",133,155,125,163],["l",144,155,136,163],["l",155,155,147,163],["l",166,155,158,163],["l",177,155,169,163],["l",188,155,180,163],["l",199,155,191,163],["l",210,155,202,163],["l",221,155,213,163],["l",40,155,222,155],["t",126,10,"A"],["t",28,172,"B"],["t",224,172,"C"],["t",14,124,"P"],["t",89,98,"Q"],["t",164,98,"R"],["t",282,134,"S"],["p","M117 41 Q130 52 143 41","s"],["t",130,64,"60\xB0","ms"],["l",32,114,87,83,"a"],["l",87,83,172,83,"a"],["l",172,83,278,120,"a"],["l",87,83,200,64,"d"],["l",87,83,172,83,"d"],["t",46,92,"i","s"],["t",188,86,"e","s"],["t",200,112,"\u03B4","s"]]}},{id:"neet-2026r-q028",pn:28,y:"Re-NEET 2026 \xB7 21 Jun",tp:"Ray Optics and Optical Instruments",st:"Combination of thin lenses",q:"The lens combination as shown in the figure, consists of two lenses, L\u2081 and L\u2082, of the focal lengths +10 cm and \u221210 cm, respectively. The position of the image formed is:",o:["60 cm to the left of the concave lens","30 cm to the right of the concave lens","60 cm to the right of the concave lens","20 cm to the left of the concave lens"],c:0,s:`For the convex lens L\u2081: u = \u221230 cm and f = +10 cm.
Using 1/v \u2212 1/u = 1/f: 1/v + 1/30 = 1/10.
1/v = 1/10 \u2212 1/30 = 2/30, so v = +15 cm.
This image acts as the object for the concave lens L\u2082, which is 3 cm away, so u\u2032 = +12 cm and f\u2032 = \u221210 cm.
Using 1/v\u2032 \u2212 1/u\u2032 = 1/f\u2032: 1/v\u2032 \u2212 1/12 = \u22121/10.
1/v\u2032 = 1/12 \u2212 1/10 = \u22121/60.
v\u2032 = \u221260 cm.
Final image is formed at 60 cm to the left of the concave lens.`,fig:{w:300,h:165,alt:"Object O (upward arrow) on a dotted principal axis, 30 cm from convex lens L1 which is 3 cm from concave lens L2.",d:[["l",8,70,292,70,"d"],["l",20,70,20,38,"a"],["t",20,86,"O","m"],["p","M200 22 C186 50 186 90 200 118 C214 90 214 50 200 22 Z"],["p","M244 22 H262 C258 50 258 90 262 118 H244 C248 90 248 50 244 22 Z"],["t",200,14,"L\u2081","m"],["t",253,14,"L\u2082","m"],["l",20,135,200,135,"b"],["l",200,135,253,135,"b"],["t",110,154,"30 cm","m"],["t",227,154,"3 cm","m"]]}},{id:"neet-2026r-q038",pn:38,y:"Re-NEET 2026 \xB7 21 Jun",tp:"Ray Optics and Optical Instruments",st:"Index correction in optical bench",q:"Which of the following measurements require \u2018index correction\u2019?",o:["Measurement of gravitational acceleration using simple pendulum","Measurement of focal length of lenses using optical bench","Measurement of speed of sound using resonance tube","Measurement of resistance of a wire using meter bridge"],c:1,s:`Index correction is an adjustment needed in experiments done on an optical bench.
It is applied while measuring the focal length of lenses using the optical bench.`},{id:"neet-2025-q002",pn:2,y:"NEET 2025",tp:"Ray Optics and Optical Instruments",st:"Compound microscope",q:"A microscope has an objective of focal length 2 cm, eyepiece of focal length 4 cm and the tube length of 40 cm. If the distance of distinct vision of eye is 25 cm, the magnification in the microscope is",o:["100","125","150","250"],c:1,s:`m = (L/f_o) \xD7 (D/f_e)
= (40/2) \xD7 (25/4)
m = 125`},{id:"neet-2025-q013",pn:13,y:"NEET 2025",tp:"Ray Optics and Optical Instruments",st:"Lenses in contact, power and magnification",q:"In a certain camera, a combination of four similar thin convex lenses are arranged axially in contact. Then the power of the combination and the total magnification in comparison to the power (p) and magnification (m) for each lens will be, respectively",o:["4p and 4m","p\u2074 and 4m","4p and m\u2074","p\u2074 and m\u2074"],c:2,s:`For a series combination of lenses:
p_eff = p\u2081 + p\u2082 + p\u2083 + p\u2084 = 4p
m_eff = m\u2081 \xD7 m\u2082 \xD7 m\u2083 \xD7 m\u2084 = m\u2074`}]})();
